"/* src/app/styles/overlays.css */\n",
"[data-act] {\n",
"  cursor: pointer;\n",
"}\n",
".toasts {\n",
"  position: fixed;\n",
"  left: 50%;\n",
"  bottom: 22px;\n",
"  transform: translateX(-50%);\n",
"  z-index: 95;\n",
"  display: flex;\n",
"  flex-direction: column;\n",
"  align-items: center;\n",
"  gap: 8px;\n",
"  width: max-content;\n",
"  max-width: calc(100vw - 32px);\n",
"  pointer-events: none;\n",
"}\n",
".player.open ~ .toasts {\n",
"  bottom: auto;\n",
"  top: 62px;\n",
"}\n",
".toast {\n",
"  pointer-events: auto;\n",
"  display: flex;\n",
"  align-items: center;\n",
"  gap: 10px;\n",
"  background: rgba(18, 22, 19, .96);\n",
"  border: 1px solid var(--line);\n",
"  border-radius: 14px;\n",
"  padding: 9px 8px 9px 16px;\n",
"  color: var(--txt);\n",
"  font-size: 14px;\n",
"  line-height: 1.35;\n",
"  box-shadow: 0 10px 30px rgba(0, 0, 0, .5);\n",
"  animation: toast-in .22s ease-out;\n",
"}\n",
".toast .tx b {\n",
"  color: var(--accent);\n",
"}\n",
".toast button {\n",
"  border: 0;\n",
"  cursor: pointer;\n",
"  font: inherit;\n",
"  font-weight: 800;\n",
"}\n",
".toast .ta {\n",
"  background: var(--accent);\n",
"  color: #04170e;\n",
"  border-radius: 10px;\n",
"  padding: 6px 13px;\n",
"  font-size: 13.5px;\n",
"}\n",
".toast .tx-close {\n",
"  background: none;\n",
"  color: var(--dim);\n",
"  padding: 4px 8px;\n",
"  font-size: 14px;\n",
"}\n",
".toast .tx-close:hover {\n",
"  color: var(--txt);\n",
"}\n",
"@keyframes toast-in {\n",
"  from {\n",
"    opacity: 0;\n",
"    transform: translateY(8px);\n",
"  }\n",
"  to {\n",
"    opacity: 1;\n",
"    transform: none;\n",
"  }\n",
"}\n",
"@media (prefers-reduced-motion: reduce) {\n",
"  .toast {\n",
"    animation: none;\n",
"  }\n",
"}\n",
"@media (max-width: 700px) {\n",
"  .toasts {\n",
"    bottom: calc(84px + env(safe-area-inset-bottom));\n",
"  }\n",
"  #ppip {\n",
"    display: none !important;\n",
"  }\n",
"}\n",
"@media (display-mode: standalone) {\n",
"  header {\n",
"    padding-top: max(14px, env(safe-area-inset-top));\n",
"  }\n",
"  .player .bar {\n",
"    padding-top: max(10px, env(safe-area-inset-top));\n",
"  }\n",
"  .sheet .close {\n",
"    top: max(16px, calc(env(safe-area-inset-top) + 8px));\n",
"  }\n",
"  .player.open ~ .toasts {\n",
"    top: calc(62px + env(safe-area-inset-top));\n",
"  }\n",
"}\n",
"@media (display-mode: standalone) and (max-width: 700px) {\n",
"  #tabbar {\n",
"    bottom: calc(8px + env(safe-area-inset-bottom));\n",
"  }\n",
"  main {\n",
"    padding-bottom: calc(104px + env(safe-area-inset-bottom));\n",
"  }\n",
"}\n",
".set {\n",
"  padding: 26px 30px 30px;\n",
"}\n",
".set-top {\n",
