"  font-size: 12px;\n",
"  color: var(--dim);\n",
"  white-space: nowrap;\n",
"  overflow: hidden;\n",
"  text-overflow: ellipsis;\n",
"}\n",
".rd-modes {\n",
"  display: flex;\n",
"  gap: 4px;\n",
"  flex: 0 0 auto;\n",
"}\n",
".rd-mode {\n",
