"  user-select: none;\n",
"}\n",
".avatar[hidden] {\n",
"  display: none;\n",
"}\n",
".hdr-icons .ic.me.has-profile {\n",
"  border-color: transparent;\n",
"  font-weight: 900;\n",
"  font-size: 15px;\n",
"  line-height: 1;\n",
"}\n",
"@media (max-width: 700px) {\n",
"  header .avatar.desktop {\n",
"    display: none;\n",
"  }\n",
"}\n",
".pick {\n",
"  position: fixed;\n",
"  inset: 0;\n",
"  z-index: 90;\n",
"  display: none;\n",
"  overflow-y: auto;\n",
"  -webkit-overflow-scrolling: touch;\n",
"  background:\n",
"    radial-gradient(\n",
"      1000px 520px at 50% -10%,\n",
"      #12211a,\n",
"      #000 70%);\n",
