".pick-input:focus {\n",
"  outline: none;\n",
"  border-color: var(--accent);\n",
"}\n",
".pick-panel {\n",
"  display: flex;\n",
"  flex-direction: column;\n",
"  align-items: center;\n",
"  max-width: 440px;\n",
"  margin: 6px 0;\n",
"}\n",
".pick-panel .pick-input {\n",
"  max-width: 260px;\n",
"  margin: 4px 0 8px;\n",
"}\n",
".pick-label {\n",
"  font-size: 13.5px;\n",
"  color: var(--dim);\n",
"  margin-top: 4px;\n",
"}\n",
".pick-row {\n",
"  display: flex;\n",
"  flex-wrap: wrap;\n",
"  justify-content: center;\n",
"  gap: 10px;\n",
"  margin-top: 8px;\n",
"}\n",
".pick-btn {\n",
"  border: 0;\n",
"  cursor: pointer;\n",
"  font: inherit;\n",
"  font-weight: 800;\n",
"  font-size: 14.5px;\n",
