"  background: rgba(255, 255, 255, .12);\n",
"  padding: 10px 18px;\n",
"  border-radius: 22px;\n",
"}\n",
".pick-btn:hover {\n",
"  background: rgba(255, 255, 255, .2);\n",
"}\n",
".pick-btn.primary {\n",
"  background: #fff;\n",
"  color: #0a0d0b;\n",
"}\n",
".pick-btn.danger {\n",
"  background: #f4665f;\n",
"  color: #1a0605;\n",
"}\n",
".pick-btn[disabled] {\n",
"  opacity: .4;\n",
