"/* src/app/styles/index.css */\n",
"</style>\n",
"</head>\n",
"<body>\n",
"  <!-- The app shell. No inline JS or CSS here: build.mjs replaces the two\n",
"       BUILD markers with the bundled stylesheet and scripts. Clicks are wired\n",
"       with data-act=\"<action>\" (see ui/actions.js), never onclick. -->\n",
"  <header>\n",
"    <div class=\"brand\">SLIME<span>WATCH</span></div>\n",
"    <nav id=\"nav\"></nav>\n",
"    <div class=\"search-box\">\n",
"      <span style=\"color:var(--dim)\">⌕</span>\n",
"      <input id=\"q\" placeholder=\"Search…\" autocomplete=\"off\">\n",
"    </div>\n",
"    <span class=\"avatar desktop\" id=\"hdr-avatar\" data-act=\"profiles\" title=\"Who's watching?\" hidden></span>\n",
"    <span class=\"logout desktop\" data-act=\"settings\" title=\"Debrid settings\" style=\"font-size:18px;line-height:1\">⚙</span>\n",
"    <span class=\"logout desktop\" data-act=\"logout\">Sign out</span>\n",
"    <!-- Phone-only header cluster, mirroring the app: dice, profile, settings. -->\n",
"    <div class=\"hdr-icons\">\n",
"      <span class=\"ic\" title=\"Surprise me\" data-act=\"surprise\">🎲</span>\n",
"      <span class=\"ic me\" id=\"hdr-me\" title=\"Who's watching?\" data-act=\"profiles\">🍿</span>\n",
"      <span class=\"ic\" title=\"Settings\" data-act=\"settings\">⚙</span>\n",
"    </div>\n",
"  </header>\n",
"  <div class=\"pills-row\" id=\"pills\"></div>\n",
"  <main id=\"main\"></main>\n",
"  <!-- Floating tab bar (phones only). Five tabs (Home, Search, Live, Read, My Stuff); the rest has no\n",
"       Reading section — Movies/Series/Anime live in the pills, exactly as they\n",
"       do on iOS Home. -->\n",
"  <nav id=\"tabbar\"></nav>\n",
"\n",
"  <div class=\"modal\" id=\"modal\"><div class=\"sheet\" id=\"sheet\"></div></div>\n",
"  <div class=\"modal\" id=\"setmodal\"><div class=\"sheet\" id=\"setsheet\" style=\"max-width:540px;margin-top:70px\"></div></div>\n",
"  <!-- \"Who's watching?\" (profiles.js) — above the player and the reader. -->\n",
"  <div class=\"pick\" id=\"pick\" role=\"dialog\" aria-modal=\"true\" aria-label=\"Who's watching?\" aria-hidden=\"true\"></div>\n",
"  <div class=\"player\" id=\"player\">\n",
"    <div class=\"bar\">\n",
"      <span class=\"pt\" id=\"ptitle\"></span>\n",
"      <span class=\"pbadge\" id=\"pbadge\" style=\"display:none\">⚡ DEBRID</span>\n",
"      <label style=\"color:var(--dim);font-size:13px\">Source</label>\n",
"      <select id=\"psel\"></select>\n",
"      <button class=\"x\" id=\"ppip\" data-act=\"player-pip\" title=\"Picture in Picture\" style=\"display:none\">⧉ PiP</button>\n",
"      <button class=\"x\" id=\"pfs\" data-act=\"player-fullscreen\" title=\"Fullscreen (f)\">⛶ Fullscreen</button>\n",
"      <button class=\"x\" data-act=\"player-close\" title=\"Close (Esc)\">✕ Close</button>\n",
"    </div>\n",
"    <div class=\"stage\">\n",
"      <video id=\"pvideo\" controls playsinline preload=\"auto\" style=\"display:none\"></video>\n",
"      <!-- NO sandbox attribute, deliberately. Tested: VidLink and VidFast detect it\n",
"           and render \"Please Disable Sandbox\" instead of playing, and VidFast\n",
"           refuses even the narrow form that keeps allow-popups. These providers\n",
"           monetise through popups, so blocking them blocks playback. Ads are\n",
"           dealt with by NOT loading their page — the ad-free extractor tier — and\n",
"           by a browser content blocker for the times an embed is the only option. -->\n",
"      <iframe id=\"pframe\" allowfullscreen\n",
"              allow=\"autoplay; fullscreen; encrypted-media; picture-in-picture\"\n",
"              referrerpolicy=\"no-referrer\" style=\"display:none\"></iframe>\n",
"      <div class=\"ploading on\" id=\"ploading\">Finding the best source…</div>\n",
"      <div class=\"upnext\" id=\"pupnext\"></div>\n",
"    </div>\n",
"    <div class=\"hint\" id=\"phint\"></div>\n",
"  </div>\n",
"  <!-- Toast stack (update notice, install hint); must stay AFTER #player — the\n",
"       CSS moves it to the top while the player is open via .player.open ~ .toasts -->\n",
