"    if (opts.lost && isPlayerOpen()) closePlayer();\n",
"    Object.assign(ui, {\n",
"      open: true,\n",
"      closable: !!cur && !opts.lost && !opts.boot,\n",
"      mode: \"loading\",\n",
"      adding: false,\n",
"      draft: \"\",\n",
"      confirm: \"\",\n",
"      target: null,\n",
"      note: \"\",\n",
"      error: \"\",\n",
"      boot: !!opts.boot,\n",
"      lost: !!opts.lost\n",
