"    show(true);\n",
"    paint();\n",
"    await refresh();\n",
"  }\n",
"  async function refresh() {\n",
"    ui.mode = \"loading\";\n",
"    ui.error = \"\";\n",
"    paint();\n",
"    const r = await ctl.list();\n",
"    if (!ui.open) return;\n",
"    if (r.unconfigured) {\n",
"      if (ui.boot) {\n",
"        closeProfiles(true);\n",
"        initSync({});\n",
"        return;\n",
"      }\n",
"      ui.closable = true;\n",
"      ui.mode = \"unconfigured\";\n",
"      paint();\n",
"      return;\n",
"    }\n",
"    if (r.error === \"signed-out\") {\n",
"      location.href = \"/login\";\n",
"      return;\n",
"    }\n",
"    if (r.error) {\n",
"      ui.mode = \"error\";\n",
"      ui.error = errorText(r.error);\n",
"      if (ui.boot) ui.closable = true;\n",
"      paint();\n",
"      return;\n",
"    }\n",
"    ui.profiles = r.profiles;\n",
"    ui.mode = \"grid\";\n",
"    const cur = currentProfile();\n",
"    if (ui.lost && cur) ui.note = r.profiles.some((p) => p.id === cur.id) ? `Pick ${cur.name} again to keep syncing.` : `${cur.name} was removed. Who's watching?`;\n",
"    if (!r.profiles.length) {\n",
"      ui.adding = true;\n",
"      ui.note = ui.note || \"Add your name \\u2014 your lists and history stay yours.\";\n",
"    }\n",
"    paint();\n",
"  }\n",
"  function closeProfiles(force = false) {\n",
"    if (!ui.open || !ui.closable && !force) return false;\n",
"    ui.open = false;\n",
"    show(false);\n",
"    const el2 = $(\"pick\");\n",
"    if (el2) el2.innerHTML = \"\";\n",
"    return true;\n",
"  }\n",
"  function escProfiles() {\n",
"    if (!ui.open) return false;\n",
"    if (ui.mode === \"grid\" && ui.adding && ui.profiles.length) {\n",
"      ui.adding = false;\n",
"      ui.error = \"\";\n",
"      paint();\n",
"      return true;\n",
"    }\n",
"    if (ui.mode === \"import\" || ui.mode === \"delete\" || ui.mode === \"unsent\") {\n",
"      ui.mode = \"grid\";\n",
"      ui.error = \"\";\n",
"      paint();\n",
"      return true;\n",
"    }\n",
"    closeProfiles();\n",
"    return true;\n",
"  }\n",
"  async function pick2(id, opts = {}) {\n",
"    const p = ui.profiles.find((x) => x.id === id);\n",
"    if (!p || ui.mode === \"busy\") return;\n",
"    const cur = currentProfile();\n",
"    if (cur && cur.id === id && ui.closable && !opts.importLocal && syncStatus().state !== \"no-profile\") {\n",
"      closeProfiles();\n",
"      return;\n",
"    }\n",
"    ui.target = p;\n",
"    ui.error = \"\";\n",
"    ui.mode = \"busy\";\n",
"    ui.busyText = cur && cur.id !== id ? `Switching to ${p.name}\\u2026` : `Opening ${p.name}\\u2026`;\n",
"    paint();\n",
"    const r = await ctl.select(p, opts);\n",
"    if (r.needsImport) {\n",
"      ui.mode = \"import\";\n",
"      paint();\n",
"      return;\n",
"    }\n",
"    if (r.unsent) {\n",
"      ui.mode = \"unsent\";\n",
"      paint();\n",
"      return;\n",
"    }\n",
"    if (r.error) {\n",
"      ui.mode = \"grid\";\n",
"      ui.error = errorText(r.error);\n",
"      paint();\n",
"      if (r.error === \"no-such-profile\") refresh();\n",
"      return;\n",
"    }\n",
"    if (r.switched) {\n",
"      try {\n",
"        askSession().reset();\n",
"      } catch {\n",
"      }\n",
"    }\n",
