"  var askCta = (q) => `<button class=\"ask-cta\" data-act=\"ask-open\" data-q=\"${esc(q)}\">\\u2726 Ask SlimeWatch: \\u201C${esc(q)}\\u201D</button>`;\n",
"  async function results(q) {\n",
"    const r = await api(\"search/multi?query=\" + encodeURIComponent(q));\n",
"    const items = (r?.results || []).filter((x) => x.media_type !== \"person\" && x.poster_path);\n",
"    return askCta(q) + (items.length ? `<div class=\"grid\">${items.map(card).join(\"\")}</div>` : '<div class=\"empty\">No matches for \\u201C' + esc(q) + \"\\u201D. Ask might know it from a description.</div>\");\n",
"  }\n",
"  async function viewSearch(q) {\n",
"    const main = document.getElementById(\"main\");\n",
"    const my = ++seq;\n",
"    if (!q || q.length < 2) {\n",
"      main.innerHTML = HINT;\n",
"      return;\n",
"    }\n",
"    main.innerHTML = '<div class=\"empty\">Searching\\u2026</div>';\n",
"    const html = await results(q);\n",
"    if (my === seq) main.innerHTML = html;\n",
"  }\n",
"  function viewSearchScreen(arg) {\n",
"    mode = arg === \"ask\" ? \"ask\" : \"search\";\n",
"    const ask = mode === \"ask\";\n",
"    const main = document.getElementById(\"main\");\n",
"    main.innerHTML = `<div class=\"ask-modes\" role=\"tablist\">\n",
"      <button role=\"tab\" aria-selected=\"${!ask}\" class=\"${ask ? \"\" : \"on\"}\" data-act=\"search-mode\" data-mode=\"search\">Search</button>\n",
"      <button role=\"tab\" aria-selected=\"${ask}\" class=\"${ask ? \"on\" : \"\"}\" data-act=\"search-mode\" data-mode=\"ask\">\\u2726 Ask</button>\n",
"    </div>\n",
"    <div class=\"m-search\">\n",
"      <input id=\"mq\" placeholder=\"${ask ? \"Ask SlimeWatch anything\\u2026\" : \"Search movies, shows &amp; anime\"}\" autocomplete=\"off\"\n",
"             autocapitalize=\"${ask ? \"sentences\" : \"none\"}\" enterkeyhint=\"${ask ? \"send\" : \"search\"}\" maxlength=\"1000\">\n",
"      ${ask ? '<button class=\"ask-go\" data-act=\"ask-send\">Ask</button>' : \"\"}\n",
"    </div><div id=\"mres\" data-mode=\"${mode}\">${ask ? \"\" : HINT}</div>`;\n",
"    const input = $(\"mq\");\n",
"    if (!input) return;\n",
"    if (ask) {\n",
"      askSession().onChange = renderAsk;\n",
"      input.addEventListener(\"keydown\", (e) => {\n",
"        if (e.key === \"Enter\" && !e.isComposing) {\n",
"          e.preventDefault();\n",
"          sendAsk();\n",
"        }\n",
