"    input.value = \"\";\n",
"    startAsk(q);\n",
"  }\n",
"  function openAsk(q) {\n",
"    seed = String(q || \"\").trim() || null;\n",
"    const field = $(\"q\");\n",
"    if (field) field.value = \"\";\n",
"    if (location.hash === \"#search/ask\") viewSearchScreen(\"ask\");\n",
"    else go(\"#search/ask\");\n",
"  }\n",
"  onAction(\"search-mode\", (el2) => go(el2.dataset.mode === \"ask\" ? \"#search/ask\" : \"#search\"));\n",
"  onAction(\"ask-open\", (el2) => openAsk(el2.dataset.q));\n",
"  onAction(\"ask-send\", () => sendAsk());\n",
"  onAction(\"ask-suggest\", (el2) => startAsk(el2.dataset.q));\n",
